package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseP1MigrationTest extends MigrationTestSupport {
 @Test void populatedLegacyCredentialsStayHistoricalAndFailedUpgradeRetriesUnchanged(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_p1_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("66").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID user=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('p1-upgrade@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);db.update("INSERT INTO professional_profiles(user_id,professional_type,title,verification_status,verified_at,license_number,rating,green_ocean_score) VALUES(?,'PSYCHOLOGIST','Historical self declaration','VERIFIED',CURRENT_TIMESTAMP,'HISTORICAL-CLAIM',5,100)",user);UUID app=db.queryForObject("INSERT INTO professional_verifications(professional_user_id,status,reviewed_by,reviewed_at) VALUES(?,'APPROVED',?,CURRENT_TIMESTAMP) RETURNING id",UUID.class,user,user);UUID doc=db.queryForObject("INSERT INTO professional_application_documents(application_id,original_name,content_type,byte_size,sha256,storage_key,scan_status) VALUES(?,'historical.pdf','application/pdf',100,repeat('0',64),'synthetic-old-unencrypted','CLEAN') RETURNING id",UUID.class,app);var old=db.queryForMap("SELECT title,license_number,verification_status,rating,green_ocean_score FROM professional_profiles WHERE user_id=?",user);db.execute("CREATE TABLE professional_qualification_decisions(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.columns WHERE table_schema=? AND table_name='professional_verifications' AND column_name='qualification_state'",Integer.class,schema)).isZero();db.execute("DROP TABLE professional_qualification_decisions");Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate();assertThat(db.queryForMap("SELECT title,license_number,verification_status,rating,green_ocean_score FROM professional_profiles WHERE user_id=?",user)).isEqualTo(old);assertThat(db.queryForObject("SELECT scan_status FROM professional_application_documents WHERE id=?",String.class,doc)).isEqualTo("PENDING");assertThat(db.queryForObject("SELECT professional_qualification_live(?)",Boolean.class,user)).isFalse();assertThat(db.queryForObject("SELECT count(*) FROM clinic_release_approvals",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
